local config = {
  ui_story_30760401_1_1_dialog_content = "Were you lying when you said \"<color=#FFB400>The Shadow will overrun this place</color>,\" Mr. Scam Artist?",
  ui_story_30760401_1_2_dialog_content = "Of course, I said that in a roundabout way on purpose, to make things more interesting.",
  ui_story_30760401_1_3_dialog_content = "I thought as much. Anyway, I've come as you asked, so if you have something to say, go on with it.",
  ui_story_30760401_1_4_dialog_content = "Alright then, let's go somewhere a little quieter.",
  ui_story_30760401_1_5_dialog_content = "I'm a simple man with a simple purpose, I'm bored and there's nothing to do around here. That's where you come in.",
  ui_story_30760401_1_6_dialog_content = "Usually I'd just cause some trouble for you. This time I want to avoid that, so I called you here.",
  ui_story_30760401_1_7_dialog_content = "I see. You wanted me to come here simply to alleviate your boredom... And if I refused, you would find another way to cause trouble?",
  ui_story_30760401_1_8_dialog_content = "Bingo.",
  ui_story_30760401_1_9_dialog_content = "So, why are you being so honest about this all of a sudden... Anyway, if there's something I can help you with, don't hesitate to ask.",
  ui_story_30760401_1_10_dialog_content = "Let's play a little <color=#FFB400>guessing game</color>, Navigator, using your psychic abilities.",
  ui_story_30760401_1_11_dialog_content = "I never knew that my abilities would be used for fun and games... What am I suppose to guess?",
  ui_story_30760401_1_12_dialog_content = "Let's see... For the first round, tell me when the <color=#FFB400>birdie</color> behind the door will leave?",
  ui_story_30760401_1_13_dialog_content = "A birdie behind the door? I see a green strip of cloth. Is that <color=#FFB400>Dove</color>?",
  ui_story_30760401_1_14_option_content = "I say the birdie will leave soon.",
  ui_story_30760401_1_15_dialog_content = "After all, Dove is usually quite busy. Even if she always tries to slack off, she can't afford to stay there for too long.",
  ui_story_30760401_1_16_dialog_content = "<color=#e8d9bb>After a while...</color>",
  ui_story_30760401_1_17_dialog_content = "Seems like the birdie has no plan to leave.",
  ui_story_30760401_1_18_dialog_content = "Well, as a small punishment, how about you shoo her away?",
  ui_story_30760401_1_19_option_content = "I say the birdie isn't leaving anytime soon.",
  ui_story_30760401_1_20_dialog_content = "After all, Dove loves lazing around.",
  ui_story_30760401_1_21_dialog_content = "After a while...",
  ui_story_30760401_1_22_dialog_content = "Seems like the birdie has no plan to leave.",
  ui_story_30760401_1_23_dialog_content = "Well, looks like you were right. As my punishment, I'll shoo that birdie away.",
  ui_story_30760401_1_24_dialog_content = "Why is there suddenly a punishment? And why shoo Dove away?",
  ui_story_30760401_1_25_dialog_content = "Look, her cloak is shaking. She's obviously frightened by you!",
  ui_story_30760401_1_26_dialog_content = "She'll get in the way of other people coming in and out of the door, and I don't want her to hear our following conversation...",
  ui_story_30760401_1_27_dialog_content = "No, you don't need to. I'll...",
  ui_story_30760401_1_28_dialog_content = "Dove, don't mind him!",
  ui_story_30760401_1_29_dialog_content = "Really? For your own safety, little girl, I advise you not to eavesdrop.",
  ui_story_30760401_1_30_dialog_content = "I'm not eavesdropping, I'm just slacking off, no, I mean, resting!",
  ui_story_30760401_1_A1_dialog_content = "Boo-hoo! You did me an injustice!",
  ui_story_30760401_1_31_dialog_content = "That's going too far! I'm going to win this game against you to take revenge for Dove!",
  ui_story_30760401_1_32_dialog_content = "Alright, let's continue. Your second prediction... Is this room <color=#FFB400>clean</color> or <color=#FFB400>dirty</color>?",
  ui_story_30760401_1_33_dialog_content = "No precognition required for that. The auxiliaries in the Colossus handle the cleaning.",
  ui_story_30760401_1_34_dialog_content = "What are they?",
  ui_story_30760401_1_35_dialog_content = "They're devices that can carry out all kinds of tasks for me, such as going to the Generators to gather energy.",
  ui_story_30760401_1_36_option_content = "So, this room must be clean.",
  ui_story_30760401_1_37_dialog_content = "Then, why is it dusty here?",
  ui_story_30760401_1_38_dialog_content = "This little corner... Maybe it hasn't been cleaned.",
  ui_story_30760401_1_39_option_content = "I suppose... it could be cleaner.",
  ui_story_30760401_1_40_dialog_content = "It's true. The corners are dusty.",
  ui_story_30760401_1_41_dialog_content = "PlayerName, please clean it right now. Naturally, I will help.",
  ui_story_30760401_1_42_dialog_content = "Wait? Why?",
  ui_story_30760401_1_43_dialog_content = "Because my tentacles hate dust, they've been wanting to... raise hell.",
  ui_story_30760401_1_44_dialog_content = "Alright. So please... let's put that threat to rest.",
  ui_story_30760401_1_45_dialog_content = "<color=#e8d9bb>After a session of meticulous cleaning...</color>",
  ui_story_30760401_1_46_dialog_content = "When you said you'd help, I didn't think you meant you'd just stand there sprinkling some water about with your tentacles!",
  ui_story_30760401_1_47_dialog_content = "Well, I thought you were doing such a good job that I didn't want to get in your way.",
  ui_story_30760401_1_48_dialog_content = "So, for the third prediction, <color=#FFB400>let's prepare something for any passers-by that might come this way</color>.",
  ui_story_30760401_1_49_dialog_content = "Passers-by?",
  ui_story_30760401_1_50_dialog_content = "Yes. Without knowing who will show up, we each put a <color=#FFB400>gift</color> on this table.",
  ui_story_30760401_1_51_dialog_content = "Then we ask the passer-by to choose one to take away with them.",
  ui_story_30760401_1_52_dialog_content = "I see. That means we need to guess who'll turn up?",
  ui_story_30760401_1_53_dialog_content = "I'll start us off... First, some luxurious dark velvet fabric... Then a candlestick, roses, some fine red wine.",
  ui_story_30760401_1_54_dialog_content = "Wait! Where did you get all this stuff from? I don't remember seeing these in the Colossus.",
  ui_story_30760401_1_55_dialog_content = "There are many places to store things... In my hat, my cape, my tentacles...",
  ui_story_30760401_1_56_dialog_content = "I don't care where you got them, but isn't this cheating? Didn't you say one gift?",
  ui_story_30760401_1_57_dialog_content = "Please rest assured, I promise to abide by the rules. The only gift I will offer is this <color=#FFB400>fine red wine</color>.",
  ui_story_30760401_1_58_dialog_content = "In terms of value and taste, it is the best wine available, used only to entertain the most distinguished guests.",
  ui_story_30760401_1_59_dialog_content = "The other items are merely here to fill the table and make the wine look more like a gift—",
  ui_story_30760401_1_60_dialog_content = "<color=#FFB400>Please make a note of this point.</color>",
  ui_story_30760401_1_61_dialog_content = "So, what are you preparing?",
  ui_story_30760401_1_62_dialog_content = "(A gift...? I don't have anything of value with me...)",
  ui_story_30760401_1_63_dialog_content = "(My only advantage now is knowing that there are more girls on this Colossus than there are guys!)",
  ui_story_30760401_1_64_option_content = "Place a pen on the table",
  ui_story_30760401_1_65_dialog_content = "<color=#e8d9bb>After a while...</color>",
  ui_story_30760401_1_66_dialog_content = "Huh? You want me to choose one of these two gifts? Can I really take one...?",
  ui_story_30760401_1_67_dialog_content = "I don't like wine, so I'll take this.",
  ui_story_30760401_1_68_dialog_content = "(As expected, Vice actually chooses the gift I prepared!)",
  ui_story_30760401_1_69_dialog_content = "It looks like you've won.",
  ui_story_30760401_1_70_option_content = "Place some desserts on the table",
  ui_story_30760401_1_71_dialog_content = "<color=#e8d9bb>After a while...</color>",
  ui_story_30760401_1_72_dialog_content = "A gift?",
  ui_story_30760401_1_73_dialog_content = "Hmm... Well... I guess it'll be this...",
  ui_story_30760401_1_74_dialog_content = "A winged girl passes by. Although she hesitates, she eventually takes the desserts you prepared.",
  ui_story_30760401_1_75_dialog_content = "It looks like you've won.",
  ui_story_30760401_1_76_dialog_content = "So, now for the <color=#FFB400>last prediction</color>, which also happens to be the most important one. Please listen carefully—",
  ui_story_30760401_1_77_dialog_content = "<color=#FFB400>Who will be the next person to enter this room?</color>",
  ui_story_30760401_1_78_dialog_content = "Again? How am I supposed to guess that? Isn't that a little too difficult?",
  ui_story_30760401_1_79_dialog_content = "Last time it was about passing by, now it's about entering. As the owner of the Colossus, you should know everyone on board.",
  ui_story_30760401_1_80_dialog_content = "As a matter of fact, you did a very good job just now.",
  ui_story_30760401_1_81_dialog_content = "Well, let me think it over first.",
  ui_story_30760401_1_82_dialog_content = "Of course, both of us need some time to think this over...",
  ui_story_30760401_1_83_dialog_content = "(Well, according to the logic just now...)",
  ui_story_30760401_1_84_option_content = "I think...",
  ui_story_30760401_1_85_dialog_content = "Huh? Where's Kleken? I just looked down for a moment and now he's disappeared!",
  ui_story_30760401_1_86_dialog_content = "Did he go outside...? Could he be trying to cheat?",
  ui_story_30760401_1_87_dialog_content = "Well, it's quite nice here. I originally only planned to come by for a casual visit... I didn't expect you to be <color=#FFB400>so thoughtful</color>.",
  ui_story_30760401_1_88_dialog_content = "(Sh-Sh-Shadowlord...!?)",
  ui_story_30760401_1_89_dialog_content = "It's quiet, and I can enjoy my privacy. <color=#FFB400>There aren't any nobodies gathering at my door</color>. A fine venue indeed, well done.",
  ui_story_30760401_1_90_dialog_content = "I, I just...",
  ui_story_30760401_1_91_dialog_content = "Even the floor is spotless. <color=#FFB400>Have the corners been cleaned as well</color>?",
  ui_story_30760401_1_92_dialog_content = "(Does this mean...)",
  ui_story_30760401_1_93_dialog_content = "<color=#FFB400>A velvet tablecloth, red wine...</color> You've been asking around about my favorite things, haven't you?",
  ui_story_30760401_1_94_dialog_content = "You really are quite interesting, PlayerName...",
  ui_story_30760401_1_95_dialog_content = "(Was Kleken secretly setting this up all along!?)",
  ui_story_30760401_1_96_dialog_content = "(Couldn't you simply tell me that Istvan was coming to visit!?)",
  ui_story_30760401_1_97_dialog_content = "Of course, I said that in a roundabout way on purpose, only to make things more interesting.",
  ui_story_30760401_1_98_dialog_content = "(Ah... Is that what he meant...?)",
  ui_story_30760401_1_99_dialog_content = "Good. I can see your earnestness. Then I believe you won't disappoint me in the conversation we're about to have.",
  ui_story_30760401_1_100_dialog_content = "Huh? What—!?",
  ui_story_30760301_1_1_dialog_content = "What do I do with this <color=#FFB400>Dibury's Map</color>? I really have no clue.",
  ui_story_30760301_1_2_dialog_content = "It's very simple. You draw a class card after selecting a piece.",
  ui_story_30760301_1_3_dialog_content = "I drew the Civilian class card.",
  ui_story_30760301_1_4_dialog_content = "Lucky me, I got the Scam Artist card.",
  ui_story_30760301_1_5_dialog_content = "Wait... Is that class card even in this game? You're not cheating, are you?",
  ui_story_30760301_1_6_dialog_content = "Of course not. Take a look for yourself.",
  ui_story_30760301_1_7_dialog_content = "Hmm, <color=#FFB400>it really does say Scam Artist on the card</color>...",
  ui_story_30760301_1_8_dialog_content = "We've encountered thugs. It's time to roll the dice. You need both your Strategy and Combat to be higher than 6.",
  ui_story_30760301_1_9_dialog_content = "Strategy 8, Combat 9! I made it!",
  ui_story_30760301_1_10_dialog_content = "Strategy 13, Combat 4! It looks like I'll have to draw an Event card.",
  ui_story_30760301_1_11_dialog_content = "The Event card reads, \"Your secret document has been confiscated and you're thrown into a dungeon.\"",
  ui_story_30760301_1_12_dialog_content = "Every time I see this thing, it always reminds me of <color=#FFB400>a previous experience</color>. Would you like to hear about it?",
  ui_story_30760301_1_13_option_content = "Tell me about it.",
  ui_story_30760301_1_14_dialog_content = "You seem eager. I'll have to do a better job of telling about it then.",
  ui_story_30760301_1_15_option_content = "Not interested. Why do you tell me a story all of a sudden?",
  ui_story_30760301_1_16_dialog_content = "Well, that just won't do. Trust me, it's a good story. I'm afraid I'll have to force you to listen.",
  ui_story_30760301_1_17_dialog_content = "<color=#e8d9bb>In an underground cavity buried by rubbles</color>",
  ui_story_30760301_1_18_dialog_content = "If I must die like this, so be it. It's just that...",
  ui_story_30760301_1_19_dialog_content = "Is anybody there? Please, help us!",
  ui_story_30760301_1_20_dialog_content = "Children, don't gather around my feet.",
  ui_story_30760301_1_21_dialog_content = "We're scared!!!",
  ui_story_30760301_1_22_dialog_content = "Don't move. There's a hole here.",
  ui_story_30760301_1_24_dialog_content = "Are you the Shadowlord?",
  ui_story_30760301_1_25_dialog_content = "No, I'm not. You can call me Kleken, or Swindler.",
  ui_story_30760301_1_26_dialog_content = "What do we do now, Mr. Swindler?",
  ui_story_30760301_1_27_dialog_content = "Well, we could play a while. I have something here—it just so happens that I've brought this <color=#FFB400>Dibury's Map</color> with me. It's better than sitting around doing nothing.",
  ui_story_30760301_1_28_dialog_content = "Wow, that's amazing! Why do you have this game with you?",
  ui_story_30760301_1_29_dialog_content = "I bought a lot of things on my way here.",
  ui_story_30760301_1_30_dialog_content = "Wait a second!",
  ui_story_30760301_1_31_dialog_content = "What's the point of this random recollection?",
  ui_story_30760301_1_32_dialog_content = "It's a story about me and the little girls buried underground.",
  ui_story_30760301_1_33_dialog_content = "No, no, I want to know who the little girls are, and what did you mean by crawling about your feet?",
  ui_story_30760301_1_34_dialog_content = "Why take out Dibury's Map? And what in the world did you mean by buying a lot on the way there?",
  ui_story_30760301_1_35_dialog_content = "Well, let me start from the beginning...",
  ui_story_30760301_1_36_dialog_content = "<color=#e8d9bb>About one year ago...</color>",
  ui_story_30760301_1_37_dialog_content = "Have you heard about the <color=#FFB400>thugs</color> oat the edge of Umbraton?",
  ui_story_30760301_1_38_dialog_content = "I know.",
  ui_story_30760301_1_39_dialog_content = "They've kidnapped two little girls associated with our organization and have asked me to negotiate with them.",
  ui_story_30760301_1_40_dialog_content = "But I have to attend a meeting held by the Guild today, a fact of which they are well aware of.",
  ui_story_30760301_1_41_dialog_content = "The thugs don't know what I look like, so I want you to deal with this in my stead. You are, after all, very experienced in the art of deception.",
  ui_story_30760301_1_42_dialog_content = "You want me to impersonate you? Interesting. Got it.",
  ui_story_30760301_1_43_dialog_content = "Whether it's paper or food, bring however much you need. There's some jerky and bread on the table. Take it.",
  ui_story_30760301_1_44_dialog_content = "Are you the leader of the Istvan Gang?",
  ui_story_30760301_1_45_dialog_content = "Where are the hostages? Let me make sure they're safe.",
  ui_story_30760301_1_46_dialog_content = "They're chilling over there. Don't worry, we have something to entertain your girls.",
  ui_story_30760301_1_48_dialog_content = "Tell me what you want for releasing them. The ball is in your court.",
  ui_story_30760301_1_49_dialog_content = "Just sign this document and I'll let them go.",
  ui_story_30760301_1_51_dialog_content = "\"Transfer of Rights\"...",
  ui_story_30760301_1_52_dialog_content = "No problem. Signed.",
  ui_story_30760301_1_53_dialog_content = "You are so hasty. Are you sure you've read it carefully?",
  ui_story_30760301_1_54_dialog_content = "It says that the rights of the Istvan Gang to cooperate with the Guild will be transferred to you.",
  ui_story_30760301_1_55_dialog_content = "You chose to carry out this kidnapping today in order to sabotage the meeting between the Istvan Gang and the Guild, correct?",
  ui_story_30760301_1_56_dialog_content = "Correct. It's refreshing being able to talk with someone so intuitive. You certainly are worthy of being in charge of the Istvan Gang.",
  ui_story_30760301_1_57_dialog_content = "Wait... Since when did the Shadowlord have daughters!?",
  ui_story_30760301_1_58_dialog_content = "Of course he doesn't. Perhaps they had gathered misleading intel from somewhere, hence the misunderstanding.",
  ui_story_30760301_1_59_dialog_content = "Anyway, allow me to continue the story...",
  ui_story_30760301_1_60_dialog_content = "Yes, all signed, indeed.",
  ui_story_30760301_1_61_dialog_content = "Now that you've signed it as we requested... The hostages are in that hut. Feel free to take them.",
  ui_story_30760301_1_62_dialog_content = "So, the thugs allowed you to take the hostages and let you go?",
  ui_story_30760301_1_63_dialog_content = "What would you do if you were in their position? Would you let us go?",
  ui_story_30760301_1_64_option_content = "I'd let you go, as agreed.",
  ui_story_30760301_1_65_dialog_content = "After all, you did sign the agreement, as requested. If I didn't let you go, my credibility would be ruined.",
  ui_story_30760301_1_66_dialog_content = "Thugs like that don't care about credibility.",
  ui_story_30760301_1_67_option_content = "Of course I wouldn't let you go.",
  ui_story_30760301_1_68_dialog_content = "If you retaliated or tore up the agreement afterward, the kidnapping would have been in vain.",
  ui_story_30760301_1_69_dialog_content = "If the Shadowlord had signed the agreement, the Istvan Gang would never go back on its promise. This is what you call credibility.",
  ui_story_30760301_1_70_dialog_content = "So, you really went into the hut? Weren't you afraid that they had set a trap?",
  ui_story_30760301_1_71_dialog_content = "I had to go in, of course. The safety of the hostages was my priority.",
  ui_story_30760301_1_72_dialog_content = "What happened next?",
  ui_story_30760301_1_73_dialog_content = "When I went in to untie the hostages, I found two little girls sleeping. And then...",
  ui_story_30760301_1_74_dialog_content = "<size=50>Boom!</size>",
  ui_story_30760301_1_75_dialog_content = "They detonated an underground bomb!",
  ui_story_30760301_1_76_dialog_content = "A bomb? Was anyone hurt?",
  ui_story_30760301_1_77_dialog_content = "So this is where the story of you and the little girls buried in rubbles begins?",
  ui_story_30760301_1_78_dialog_content = "Yes. Although the explosion was not a huge one, I still expended a great deal of my strength to defend against it completely.",
  ui_story_30760301_1_79_dialog_content = "We couldn't get out right away, as I needed some time to recover.",
  ui_story_30760301_1_80_dialog_content = "Okay... But you said that you pulled out the Dibury's Map? Did you really end up playing in it?",
  ui_story_30760301_1_81_dialog_content = "We did. But soon after we started, they somehow swallowed the dice, so we had to chat in those underground ruins.",
  ui_story_30760301_1_82_dialog_content = "You joined the Istvan Gang not long ago, I seem to recall.",
  ui_story_30760301_1_83_dialog_content = "Oh, you recognize us. We're <color=#FFB400>Patty</color> and <color=#FFB400>Patsy</color>.",
  ui_story_30760301_1_84_dialog_content = "How did you get caught? They don't look particularly strong...",
  ui_story_30760301_1_85_dialog_content = "We were out playing, then passed out from hunger by the side of the road. When we opened our eyes, we were already kidnapped.",
  ui_story_30760301_1_86_dialog_content = "No wonder you're always lying on the ground. The Shadowlord must have prepared the food for you.",
  ui_story_30760301_1_87_dialog_content = "Jerky!",
  ui_story_30760301_1_88_dialog_content = "Bread!",
  ui_story_30760301_1_89_dialog_content = "Nom, nom...",
  ui_story_30760301_1_90_dialog_content = "We're full!",
  ui_story_30760301_1_91_dialog_content = "Then let's get to work. Back up a little bit... I need to clear the rubbles above us.",
  ui_story_30760301_1_92_dialog_content = "What huge, powerful tentacles! Where did they come from?",
  ui_story_30760301_1_93_dialog_content = "That doesn't matter. <color=#FFB400>Just take it as an illusion</color>. Now, it's your turn to break a sweat...",
  ui_story_30760301_1_94_dialog_content = "There are probably only a few thugs guarding their base. I know where they are. Let's go and bite them...",
  ui_story_30760301_1_95_dialog_content = "After that, we took their base with ease. Happy ending.",
  ui_story_30760301_1_96_dialog_content = "Wait... Geez, now you got me saying it!",
  ui_story_30760301_1_97_dialog_content = "Why did you think that there were only a few thugs guarding their base?",
  ui_story_30760301_1_98_dialog_content = "Simple, because their boss went to the Guild with his lackeys and the agreement.",
  ui_story_30760301_1_99_dialog_content = "The agreement you signed? That must not have passed for being legitimate.",
  ui_story_30760301_1_100_dialog_content = "No, I signed Istvan's name and used his seal.",
  ui_story_30760301_1_101_dialog_content = "That document was indeed valid, unfortunately...",
  ui_story_30760301_1_102_dialog_content = "<color=#e8d9bb>At the secret meeting</color>",
  ui_story_30760301_1_103_dialog_content = "Who are you, and what are you doing here, strangers?",
  ui_story_30760301_1_104_dialog_content = "Are you the boss of the Guild? From today on, our gang will be working with you.",
  ui_story_30760301_1_105_dialog_content = "Here's the \"Transfer of Rights\", personally signed by Istvan.",
  ui_story_30760301_1_106_dialog_content = "An agreement? Isn't that the <color=#FFB400>Dibury's Map</color>? Oh, it's from the same batch we put out recently.",
  ui_story_30760301_1_107_dialog_content = "But it is clearly written on this paper that... No way! <color=#FFB400>This must be an illusion</color>!",
  ui_story_30760301_1_108_dialog_content = "Damn it! Istvan tricked us!? How!?",
  ui_story_30760301_1_109_dialog_content = "Mr. Istvan happens to be here with a group of attendants. Would you like to meet him?",
  ui_story_30760301_1_110_dialog_content = "You've come all this way. Please, take a seat...",
  ui_story_30760301_1_111_dialog_content = "And so the thugs were sent straight into the hands of the Shadowlord. Happy ending again.",
  ui_story_30760301_1_112_dialog_content = "The thugs actually took the Dibury's Map? How did they even mistake it for an agreement?",
  ui_story_30760301_1_113_dialog_content = "They confirmed it over and over again. If it were you, would you have been fooled by my ruse?",
  ui_story_30760301_1_114_option_content = "Well, if you were the one who gave it to me... Maybe?",
  ui_story_30760301_1_115_dialog_content = "It seems that you at least know me a little.",
  ui_story_30760301_1_116_option_content = "No way! I would have been able to tell!",
  ui_story_30760301_1_117_dialog_content = "It's not a bad thing to have such confidence.",
  ui_story_30760301_1_118_dialog_content = "Well then, take a look at this.",
  ui_story_30760301_1_119_dialog_content = "Huh? Isn't this the class card you drew at the beginning?",
  ui_story_30760301_1_120_dialog_content = "What's on it?",
  ui_story_30760301_1_121_dialog_content = "Hmm... Class, <color=#FFB400>Gangster</color>? How is that possible!?",
  ui_story_30760301_1_122_dialog_content = "But it clearly read <color=#FFB400>Scam Artist</color> before! Did you cheat and switch cards?",
  ui_story_30760301_1_123_dialog_content = "No, there's no Scam Artist in the game of Dibury's Map to begin with.",
  ui_story_30760301_1_124_dialog_content = "<color=#FFB400>What you saw before... Just take it as an illusion.</color>",
  ui_story_30760601_1_1_dialog_content = "The scorching sun, the burning sand...",
  ui_story_30760601_1_2_dialog_content = "Something doesn't feel quite right... <color=#FFB400>That ideal</color>... is really suspicious...",
  ui_story_30760601_1_3_dialog_content = "So why am I... running around on such a hot day...",
  ui_story_30760601_1_4_dialog_content = "And making deliveries in <color=#FFB400>Kleken's</color> place?!",
  ui_story_30760601_1_5_dialog_content = "Kleken!",
  ui_story_30760601_1_6_dialog_content = "Oh hey, you're back! You finished with the delivery?",
  ui_story_30760601_1_7_dialog_content = "Yeah, I did... You...",
  ui_story_30760601_1_8_dialog_content = "Who are you?",
  ui_story_30760601_1_9_dialog_content = "Aww... Poor little thing, you've been running up and down the beach making deliveries for me all day.",
  ui_story_30760601_1_10_dialog_content = "Looks like the heat's going to your head. You can't even remember who you were so worried about...",
  ui_story_30760601_1_11_dialog_content = "Who else would be here, besides me?",
  ui_story_30760601_1_12_dialog_content = "K-Kleken?! Have you always looked this young?!",
  ui_story_30760601_1_13_dialog_content = "Congratulations! You've stumbled across yet another new truth.",
  ui_story_30760601_1_14_dialog_content = "When the weather is this hot, <color=#FFB400>I become a completely different Kleken</color>.",
  ui_story_30760601_1_15_dialog_content = "Now then, why not sit and take a break? Want some water?",
  ui_story_30760601_1_16_dialog_content = "I still have a few things here that I'd like you to deliver.",
  ui_story_30760601_1_17_dialog_content = "No... No way! I'm not helping you deliver anything! Do it yourself!",
  ui_story_30760601_1_18_dialog_content = "Now now, PlayerName, there's no need to snap at me like that. After all, you're the one who promised to help me \"finish my unfinished business.\"",
  ui_story_30760601_1_19_dialog_content = "If you've forgotten, I wouldn't mind jogging your memory a little...",
  ui_story_30760601_1_20_dialog_content = "S-Stay back! I can figure out how you tricked me all by myself, thank you!",
  ui_story_30760601_1_21_dialog_content = "Ever heard the story of the hero who went to the underwater palace and defeated a huge sea monster? It's a really nice story.",
  ui_story_30760601_1_22_dialog_content = "That's why I think you should watch your left side too, little hero...",
  ui_story_30760601_1_23_dialog_content = "Graagh!",
  ui_story_30760601_1_24_dialog_content = "I'm finally... done...",
  ui_story_30760601_1_25_dialog_content = "So why have I been putting up with this kind of danger all this time?!",
  ui_story_30760601_1_26_dialog_content = "To help me acquire these very important products, of course.",
  ui_story_30760601_1_27_dialog_content = "No, I thought you just ran into some small problems while preparing for the Ocean Sovereign...",
  ui_story_30760601_1_28_dialog_content = "So you asked me for help...",
  ui_story_30760601_1_29_dialog_content = "Who would have guessed you were going to make me find Eclipsites, and then dragged me into a mob of them?!",
  ui_story_30760601_1_30_dialog_content = "...",
  ui_story_30760601_1_31_dialog_content = "Hey, why are you being so quiet? Aren't you going to explain yourself?",
  ui_story_30760601_1_32_dialog_content = "Excuse me... What explanations do you want? I'm going to set these down for a second...",
  ui_story_30760601_1_33_dialog_content = "Are... you alright?",
  ui_story_30760601_1_34_dialog_content = "I'm fine. I nearly fell just now, that's all.",
  ui_story_30760601_1_35_dialog_content = "(How could someone as agile as Kleken \"nearly fall\"? Is he...)",
  ui_story_30760601_1_36_dialog_content = "Are you sweating?",
  ui_story_30760601_1_37_dialog_content = "Of course I am... It's burning hot, after all...",
  ui_story_30760601_1_38_dialog_content = "And yet you're still wearing such thick clothing... You burned all that energy fighting off those Eclipsites in a full suit just now.",
  ui_story_30760601_1_39_dialog_content = "But more importantly... Did you get hurt in that fight?",
  ui_story_30760601_1_40_dialog_content = "Eh... Looks like the cat's out of the bag. Not bad, PlayerName.",
  ui_story_30760601_1_41_dialog_content = "Sorry... I'm not feeling quite like myself...",
  ui_story_30760601_1_42_dialog_content = "I'm truly sorry... But I don't think I can finish this by myself anymore...",
  ui_story_30760601_1_43_dialog_content = "To tell the truth, this is the first time I've seen you risk your life like this for a job...",
  ui_story_30760601_1_44_dialog_content = "What did you take from the Eclipsites?",
  ui_story_30760601_1_45_dialog_content = "Open them and you'll know. Go ahead, open some of these boxes and take a look at what's inside.",
  ui_story_30760601_1_46_dialog_content = "Well...",
  ui_story_30760601_1_47_dialog_content = "What is this, a box full of fabric?",
  ui_story_30760601_1_48_dialog_content = "It's a box full of valuable merchandise.",
  ui_story_30760601_1_49_dialog_content = "\"Valuable merchandise\"? Are you telling me you guys were robbed by Eclipsites?",
  ui_story_30760601_1_50_dialog_content = "This isn't just a job, it has to do with my ideals... with the palaces of our hearts.",
  ui_story_30760601_1_51_dialog_content = "But I have no way of delivering this merchandise to the Umbraton merchants anymore...",
  ui_story_30760601_1_52_dialog_content = "And they're going to suffer because of it, I'm sure.",
  ui_story_30760601_1_53_dialog_content = "When I think about it like that, my conscience threatens to rip me apart.",
  ui_story_30760601_1_54_dialog_content = "Quit talking about your ideals already!",
  ui_story_30760601_1_55_dialog_content = "I'll carry the boxes! Let's get out of here before more Eclipsites find us!",
  ui_story_30760601_1_56_dialog_content = "No... You go on ahead. There's a person on the south side of the beach, deliver it to them within the next half hour.",
  ui_story_30760601_1_57_dialog_content = "It shouldn't be a problem for you. Given your speed, I think you'll make it in time!",
  ui_story_30760601_1_58_dialog_content = "Here, take it and run. Keep running forward, and don't turn back.",
  ui_story_30760601_1_59_dialog_content = "Please... Make sure this makes it into that person's hands.",
  ui_story_30760601_1_60_dialog_content = "Huh? But what about you?",
  ui_story_30760601_1_61_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_62_dialog_content = "I'll hold them off in your place...",
  ui_story_30760601_1_63_dialog_content = "Kleken?!",
  ui_story_30760601_1_64_dialog_content = "Hurry, PlayerName! Just run!",
  ui_story_30760601_1_65_dialog_content = "Graagh!",
  ui_story_30760601_1_66_dialog_content = "And so, the brave warrior ran, carrying their hopes to the final destination.",
  ui_story_30760601_1_67_dialog_content = "And when he ran into trouble, the white sea monster came to his rescue.",
  ui_story_30760601_1_68_dialog_content = "Yes... That sounds like a wonderful story. As for its name...",
  ui_story_30760601_1_69_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_70_dialog_content = "How much farther? How much time is left?",
  ui_story_30760601_1_71_dialog_content = "He sacrificed himself without hesitation... I have to deliver these things to that person!",
  ui_story_30760601_1_72_dialog_content = "I can do it... and then I'm bringing others back with me to save him!",
  ui_story_30760601_1_73_dialog_content = "*Gasping for breath* I... I finally made it...",
  ui_story_30760601_1_74_dialog_content = "Oh! You're finally here! I've been waiting all day!",
  ui_story_30760601_1_75_dialog_content = "This merchandise is really important! Are you the one I'm supposed to deliver it to?",
  ui_story_30760601_1_76_dialog_content = "Sure I am! Hmm, not bad... Here, let me take a look at what we have today.",
  ui_story_30760601_1_77_dialog_content = "There's no time! We need to go back and rescue Kleken! He's surrounded by Eclipsites!",
  ui_story_30760601_1_78_dialog_content = "Hah? But the shopkeeper over there got a message from Kleken not half an hour ago. He said...",
  ui_story_30760601_1_79_dialog_content = "He said that everything has been taken care of. Just wait for the one to show up with the goods.",
  ui_story_30760601_1_80_dialog_content = "Eh? Half an hour ago?",
  ui_story_30760601_1_81_dialog_content = "Wouldn't that have been right after I left?",
  ui_story_30760601_1_82_dialog_content = "He also said he found someone really efficient to deliver the goods this time, and no need to worry. You're that person he mentioned, I assume?",
  ui_story_30760601_1_83_dialog_content = "You're a little slow though. By our count, you should have been here ten minutes ago.",
  ui_story_30760601_1_84_dialog_content = "That guy's been making a fortune with this line of work. You must be well-paid since you work for him, huh?",
  ui_story_30760601_1_85_dialog_content = "Did you say \"making a fortune\"? Didn't the Eclipsites rob all this merchandise from you guys?",
  ui_story_30760601_1_86_dialog_content = "What the heck are you talking about? We just imported this stuff through Kleken, that's all...",
  ui_story_30760601_1_87_dialog_content = "I... need to go back and get to the bottom of this.",
  ui_story_30760601_1_88_dialog_content = "I thought you were gonna get eaten by a mob of Eclipsites!",
  ui_story_30760601_1_89_dialog_content = "I thought you sent me away to protect something you valued even more than your own life!",
  ui_story_30760601_1_90_dialog_content = "I thought you were weak from the heat and your wounds!",
  ui_story_30760601_1_91_dialog_content = "I risked the sun and the heat to deliver the merchandise, but then that merchant told me...",
  ui_story_30760601_1_92_dialog_content = "That it wasn't their stolen goods at all! Have you been stealing these stuff from other people to sell them to the merchants?",
  ui_story_30760601_1_93_dialog_content = "Just calm down, PlayerName. This is all just a misunderstanding. Let me explain...",
  ui_story_30760601_1_94_dialog_content = "When I came here, and asked for your help...",
  ui_story_30760601_1_95_dialog_content = "It was because I had a very important job to do, namely, wiping out some Eclipsites.",
  ui_story_30760601_1_96_dialog_content = "We did, in fact, run into some trouble while preparing for the Ocean Sovereign—a mob of Eclipsites that had entrenched themselves here.",
  ui_story_30760601_1_97_dialog_content = "Also, I really was wounded, and couldn't handle the heat.",
  ui_story_30760601_1_98_dialog_content = "I was too weak to do the job, and you helped me finish it. I should be thanking you.",
  ui_story_30760601_1_99_dialog_content = "But when I asked if those were your guys' merchandise, why did you...",
  ui_story_30760601_1_100_dialog_content = "I told you, it has to do with <color=#FFB400>my ideals</color>, and with the <color=#FFB400>palaces of our hearts</color>.",
  ui_story_30760601_1_101_dialog_content = "Were you dodging the question on purpose?!",
  ui_story_30760601_1_102_dialog_content = "I thought you were trying to say that the merchandise was important to realize your dreams or something!",
  ui_story_30760601_1_103_dialog_content = "I even thought you guys might be trying to save money to build a palace!",
  ui_story_30760601_1_104_dialog_content = "Hehe... Not bad at all, PlayerName. You discovered the truth even quicker than I had anticipated.",
  ui_story_30760601_1_105_dialog_content = "But if you truly think I'm doing all this for the money, then you're sorely mistaken.",
  ui_story_30760601_1_106_dialog_content = "I am, in fact, acting in the interest of my ideals.",
  ui_story_30760601_1_107_dialog_content = "What does that even mean?! Because I am, in fact, convinced you're just using me to make some money!",
  ui_story_30760601_1_108_dialog_content = "You used me to find the Eclipsites, and you used me to deliver the merchandise...",
  ui_story_30760601_1_X108_dialog_content = "But most importantly, none of those merchandises belonged to any of you.",
  ui_story_30760601_1_X109_dialog_content = "Did you ever stop to think how worried the original owners of those merchandises might be right now?",
  ui_story_30760601_1_X110_dialog_content = "Or do you think you can just pawn off whatever you steal from Eclipsites?",
  ui_story_30760601_1_109_dialog_content = "That's enough. According to the Istvan Gang's investigation on the goods, we came to the conclusion...",
  ui_story_30760601_1_110_dialog_content = "That the merchandise <color=#FFB400>has no original owner</color>.",
  ui_story_30760601_1_111_dialog_content = "So what, you're trying to say this wasn't a dirty deal, to begin with?",
  ui_story_30760601_1_112_dialog_content = "Correct. This is a very important piece of information, without it, you would definitely misunderstand my intentions.",
  ui_story_30760601_1_113_dialog_content = "When I get my payment, it is just for eliminating Eclipsites and nothing else.",
  ui_story_30760601_1_114_dialog_content = "The rest of it goes straight to the Istvan Gang.",
  ui_story_30760601_1_115_dialog_content = "You may not know it, but the Shadowlord is quite fond of performing \"good deeds.\"",
  ui_story_30760601_1_116_dialog_content = "Okay...",
  ui_story_30760601_1_117_dialog_content = "Sorry, I admit I misunderstood you a bit just now.",
  ui_story_30760601_1_118_dialog_content = "Don't mention it.",
  ui_story_30760601_1_119_dialog_content = "As a scam artist, I prefer being mistrusted to being trusted.",
  ui_story_30760601_1_120_dialog_content = "Why do I get the feeling you're being sarcastic...",
  ui_story_30760601_1_121_dialog_content = "So what's this \"ideal\" you keep talking about? You said you were acting in the interests of your ideals, right?",
  ui_story_30760601_1_122_dialog_content = "After hearing that you were selling that stuff to the merchant, I thought you were doing it for the money...",
  ui_story_30760601_1_123_dialog_content = "But using dirty money... to build a palace? In any case, at least now I know that the money isn't dirty.",
  ui_story_30760601_1_124_dialog_content = "The festival.",
  ui_story_30760601_1_125_dialog_content = "The Ocean Sovereign is still a festival, after all.",
  ui_story_30760601_1_126_dialog_content = "Uh... I'm well aware that it's a festival. What kind of answer is that?",
  ui_story_30760601_1_127_dialog_content = "Let's not be hasty. When it comes to one's ideals, they have to be described in perfect detail in order to sway the hearts of other people.",
  ui_story_30760601_1_128_dialog_content = "Once upon a time, there was a hero...",
  ui_story_30760601_1_129_dialog_content = "He was sailing the high seas on a royal vessel, in search of a legendary treasure...",
  ui_story_30760601_1_130_dialog_content = "When one day, he encountered a giant, white sea monster.",
  ui_story_30760601_1_131_dialog_content = "And with it, he discovered a magnificent, underwater palace.",
  ui_story_30760601_1_132_dialog_content = "He had finally found his treasure, so he made a pact with the white creature to exterminate the violent sea monsters plaguing the waters.",
  ui_story_30760601_1_133_dialog_content = "This is one of my favorite stories. It's called <color=#FFB400>\"An Adventurer's Voyage.\"</color>",
  ui_story_30760601_1_134_dialog_content = "A palace from a story? But isn't \"An Adventurer's Voyage\" a work of fiction?",
  ui_story_30760601_1_135_dialog_content = "Or are you saying that it has something to do with the Ocean Sovereign?",
  ui_story_30760601_1_136_dialog_content = "The reason I have come here is to investigate the relationship between the two.",
  ui_story_30760601_1_137_dialog_content = "To see that palace from the story.",
  ui_story_30760601_1_138_dialog_content = "As long as I offer my sincerity up to the Neptune, he will grant my wish and make the palace appear before me.",
  ui_story_30760601_1_139_dialog_content = "Helping everyone run the Ocean Sovereign smoothly is one way for me to show my sincerity.",
  ui_story_30760601_1_140_dialog_content = "Sounds kind of sketchy...",
  ui_story_30760601_1_141_dialog_content = "Do you think that story is based on reality? Or do you think there's no such thing as an underwater palace?",
  ui_story_30760601_1_142_option_content = "I've never read that story.",
  ui_story_30760601_1_143_dialog_content = "...",
  ui_story_30760601_1_144_dialog_content = "...",
  ui_story_30760601_1_145_dialog_content = "How odd. All of a sudden I have no idea how to continue on this topic.",
  ui_story_30760601_1_146_dialog_content = "But that's fine. It doesn't matter if you haven't read that story.",
  ui_story_30760601_1_147_option_content = "I believe it.",
  ui_story_30760601_1_148_dialog_content = "It could be that the palace in the story is a real place.",
  ui_story_30760601_1_149_dialog_content = "I'm glad you can answer and believe in it so readily.",
  ui_story_30760601_1_150_dialog_content = "I just hope that the gifts I've prepared won't disappoint you.",
  ui_story_30760601_1_151_dialog_content = "Gifts?",
  ui_story_30760601_1_152_dialog_content = "Correct. It's not every day that I encounter someone so interested in my ideals.",
  ui_story_30760601_1_153_dialog_content = "It's only proper to express my gratitude.",
  ui_story_30760601_1_154_option_content = "I don't believe it at all.",
  ui_story_30760601_1_155_dialog_content = "That story is a work of fiction, isn't it?",
  ui_story_30760601_1_156_dialog_content = "When people write stories like this, they often unintentionally allude to real events.",
  ui_story_30760601_1_157_dialog_content = "The story itself may be fictitious, but it could very well be that the author fabricated the tale based on several true accounts.",
  ui_story_30760601_1_158_dialog_content = "That's one of my ideals. Sometimes it's far away from me, sometimes it's very close by.",
  ui_story_30760601_1_159_dialog_content = "In the legend of the Ocean Sovereign, there is mention of a castle.",
  ui_story_30760601_1_160_dialog_content = "The castle in the legend, and the palace in the story... There may be some sort of relation between the two.",
  ui_story_30760601_1_161_dialog_content = "In any case, I want you to see it for yourself, as well. That's why I asked for your help.",
  ui_story_30760601_1_162_dialog_content = "Although, it seems the time is still not right... Ah well, I suppose I could try a little harder.",
  ui_story_30760601_1_163_dialog_content = "The palace at the bottom of the sea...",
  ui_story_30760601_1_164_dialog_content = "Even if all that remains are ruins, it is still an astounding sight to behold...",
  ui_story_30760601_1_165_dialog_content = "A testament to a grand and brilliant civilization that once lived here.",
  ui_story_30760601_1_166_dialog_content = "The palace? Did you... Did you really summon the undersea palace?",
  ui_story_30760601_1_167_dialog_content = "What do you think? Do you believe in its existence now?",
  ui_story_30760601_1_168_dialog_content = "Yeah, I...",
  ui_story_30760601_1_169_dialog_content = "Incidentally, this is only an illusion. If you look any closer, you will see right through my ruse.",
  ui_story_30760601_1_170_dialog_content = "I was about to say that I believe in it now... But then you cut me off.",
  ui_story_30760601_1_171_dialog_content = "Eh... Please don't be upset. Making illusions for you to see is just one of my many powers.",
  ui_story_30760601_1_172_dialog_content = "Unfortunately, I can't sustain it any longer. After all, I'm still very weak right now.",
  ui_story_30760601_1_173_dialog_content = "Wait a minute, you were resting pretty comfortably when I got back...",
  ui_story_30760601_1_174_dialog_content = "You even changed into a swimsuit from who knows where...",
  ui_story_30760601_1_175_dialog_content = "And you're still able to use your powers like this?",
  ui_story_30760601_1_176_dialog_content = "On top of that, the others told me that today's job was easy, according to you...",
  ui_story_30760601_1_177_dialog_content = "Are you really that weak right now?",
  ui_story_30760601_1_178_dialog_content = "Hmm... You seem really intent on over-analyzing things...",
  ui_story_30760601_1_179_dialog_content = "Hey... Weren't you standing up just fine a second ago?",
  ui_story_30760601_1_180_dialog_content = "Wait, crap... Why do I get the feeling you're going to trick me again?",
  ui_story_30760601_1_181_dialog_content = "Hmm, even though my strength is all but spent, I suppose I could tough it out.",
  ui_story_30760601_1_182_dialog_content = "At the very least, I'd like to give you a look at the palace I dream of seeing.",
  ui_story_30760601_1_183_dialog_content = "Fine, fine, I'm sorry for misunderstanding you again... I thought you still had some strength to spare, but I guess not.",
  ui_story_30760601_1_184_dialog_content = "I never thought you could be so determined...",
  ui_story_30760601_1_185_dialog_content = "Consider it your compensation.",
  ui_story_30760601_1_186_dialog_content = "Eh?",
  ui_story_30760601_1_187_dialog_content = "Simple and rash at times, but with a certain perceptiveness that borders on the abnormal.",
  ui_story_30760601_1_188_dialog_content = "You have the air of a hero about you.",
  ui_story_30760601_1_189_dialog_content = "And a hero is all this story needs to be complete.",
  ui_story_30760601_1_190_dialog_content = "As compensation for helping me deliver that merchandise, I have decided to let you see these spectacular sights.",
  ui_story_30760601_1_191_dialog_content = "This way, I don't have to pay you in cash, either.",
  ui_story_30760601_1_192_dialog_content = "...",
  ui_story_30760601_1_193_dialog_content = "You really didn't have to say that last part, Kleken...",
  ui_story_30760601_1_194_dialog_content = "Is that so? But I thought that as long as you received your compensation, you would be willing to help me finish the rest of my work?",
  ui_story_30760601_1_195_dialog_content = "So you really do want me to keep running errands for you?! Can't you let that sentiment last for a little longer?!",
  ui_story_30760601_1_196_dialog_content = "Of course I can't.",
  ui_story_30760601_1_197_dialog_content = "\"The Heroic Delivery\"... It makes for a pretty interesting story too, don't you think?",
  ui_story_30760601_1_198_dialog_content = "That's not a real story!!",
  ui_story_30760601_1_199_dialog_content = "I just thought of it, actually. I hope you enjoy it!"
}
return config
